insert into public.archetype_catalog(name,report_version,report,definition) values
('Architect', 'wonder-mirror-library-2026.09', $report${"name":"Architect","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Builds coherence from complexity.","elements":["Earth","Air"],"opening":"You may feel most at home when what matters has a structure capable of holding it. Your care often becomes visible in what you remember, arrange, and follow through on. The invitation is to let yourself be known before everything is in order.","gift":"structure and follow-through","need":"respect plus emotional access","shadow":"control can substitute for vulnerability","chapters":[{"title":"How your mind moves","body":"You look for the underlying mechanism. A confusing situation becomes more manageable when you can name the parts and understand how they interact. In a relationship, however, a good explanation may arrive before the other person feels heard."},{"title":"The way you come close","body":"Love can take the form of reliability: making the plan, keeping the promise, noticing what needs doing. A partner may still need the feeling beneath that competence expressed in words."},{"title":"Conditions for connection","body":"Look for respect for your thinking, reciprocal effort, and someone who can ask for emotional presence without dismissing practical care. Reliability and tenderness need not compete."},{"title":"When pressure arrives","body":"Uncertainty may pull you toward organizing, correcting, or taking charge. Notice when a shared problem quietly becomes your project and the other person loses a voice."},{"title":"A way back to each other","body":"Before proposing a solution, ask what landed badly. Reflect back their experience, name your part, and agree on one change together. Understanding is not the same as agreeing with every interpretation."},{"title":"A practice for this week","body":"Once this week, say what you need before describing how you intend to solve it. Leave enough silence for someone else to respond."}],"prompt":"Where am I making myself useful when I would rather make myself known?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Builds coherence from complexity.","elements":["Earth","Air"],"prototype":{"cognitive_systemizing":0.82,"structure_preference":0.68,"competence_identity":0.72,"decisiveness":0.48,"value_achievement":0.42},"signature":{"big5.conscientiousness":0.7,"behavior.precision":0.82,"behavior.agency":0.42,"jung.perceiving":-0.55},"relational":{"gift":"structure and follow-through","need":"respect plus emotional access","shadow":"control can substitute for vulnerability"}}$model$::jsonb),
('Seer', 'wonder-mirror-library-2026.09', $report${"name":"Seer","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Perceives patterns beneath the obvious.","elements":["Air","Ether","Water"],"opening":"You may notice the meaning beneath the sentence and the pattern beneath the event. Your attention can make another person feel remarkably visible. It also deserves a boundary: perception is an invitation to inquire, not proof that you already know.","gift":"nuance and perception","need":"depth without premature certainty","shadow":"interpretation can replace direct communication","chapters":[{"title":"How your mind moves","body":"You keep several explanations alive at once. Context, contradictions, and subtle shifts matter to you. This makes complexity interesting, though sometimes a straightforward answer gets buried beneath its possible meanings."},{"title":"The way you come close","body":"Intimacy may begin with a conversation that goes somewhere neither person expected. You bring attentive questions and an appetite for inner life. Let the other person surprise your interpretation."},{"title":"Conditions for connection","body":"You may thrive with curiosity, emotional candor, and room to think aloud without being forced into immediate certainty. Depth also needs practical availability."},{"title":"When pressure arrives","body":"A small change can become a large interpretive project. When evidence is thin, distinguish what happened from what you fear it means."},{"title":"A way back to each other","body":"Offer your reading as a question: “I noticed this; have I understood it?” Listen to the answer before constructing the next explanation."},{"title":"A practice for this week","body":"Write three columns: what I observed, what I inferred, and what I could ask. Take the question into the actual relationship."}],"prompt":"What would I learn if I asked instead of interpreting?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Perceives patterns beneath the obvious.","elements":["Air","Ether","Water"],"prototype":{"cognitive_contextual":0.82,"ambiguity_tolerance":0.65,"value_meaning":0.68,"value_knowledge":0.58,"vulnerability_openness":0.35},"signature":{"big5.openness":0.8,"jung.intuition":0.82,"motives.meaning":0.78,"behavior.precision":-0.15},"relational":{"gift":"nuance and perception","need":"depth without premature certainty","shadow":"interpretation can replace direct communication"}}$model$::jsonb),
('Explorer', 'wonder-mirror-library-2026.09', $report${"name":"Explorer","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Expands through encounter, movement, and possibility.","elements":["Air","Fire"],"opening":"Possibility may be one of your forms of oxygen. You discover yourself through encounters, experiments, and changes of scene. A lasting bond can offer somewhere to return without closing the world around you.","gift":"expansion and play","need":"freedom that still has relational substance","shadow":"novelty can become avoidance","chapters":[{"title":"How your mind moves","body":"You often learn by trying. An unfamiliar setting can reveal something that careful planning could not. Your openness becomes especially useful when paired with the patience to notice what an experience actually teaches."},{"title":"The way you come close","body":"You bring play, invitations, and a willingness to interrupt stale routines. Shared novelty can open intimacy, but ordinary days reveal whether attention survives without stimulation."},{"title":"Conditions for connection","body":"You may need movement, choice, and a partner who is interested in discovery. You also deserve clear agreements about what freedom means to each of you."},{"title":"When pressure arrives","body":"When connection becomes difficult, a new possibility may seem more compelling than the unfinished conversation. Ask whether you want expansion or relief."},{"title":"A way back to each other","body":"Return at an agreed time, even if you still feel restless. Name the constraint you experienced without making your partner responsible for all discomfort."},{"title":"A practice for this week","body":"Create one small adventure and keep one ordinary promise. Notice which kind of closeness each makes possible."}],"prompt":"What am I willing to stay curious about after the novelty has passed?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Expands through encounter, movement, and possibility.","elements":["Air","Fire"],"prototype":{"novelty_orientation":0.86,"value_freedom":0.76,"autonomy_need":0.48,"ambiguity_tolerance":0.48,"social_initiation":0.28},"signature":{"big5.openness":0.78,"jung.perceiving":0.72,"motives.discovery":0.88,"behavior.pace_stability":-0.62},"relational":{"gift":"expansion and play","need":"freedom that still has relational substance","shadow":"novelty can become avoidance"}}$model$::jsonb),
('Sovereign', 'wonder-mirror-library-2026.09', $report${"name":"Sovereign","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Creates direction and consequential outcomes.","elements":["Fire","Earth"],"opening":"You may move toward life with a strong sense of agency. Decisions, responsibility, and consequential work can feel natural to you. Intimacy asks for a different kind of strength: influence that leaves room for another person to remain fully themselves.","gift":"agency and protection","need":"mutual respect and a strong counterpart","shadow":"agency can become control","chapters":[{"title":"How your mind moves","body":"You look for the point at which understanding can become action. You may prefer a clear position to an unresolved discussion. Slower deliberation can still contain information worth having."},{"title":"The way you come close","body":"You can offer direction, commitment, and protection. A partner needs to feel chosen as an equal participant, rather than fitted into an already completed plan."},{"title":"Conditions for connection","body":"Mutual respect matters. Look for someone who can disagree, make requests, and carry their own commitments while remaining emotionally available."},{"title":"When pressure arrives","body":"Pressure may sharpen certainty and make negotiation feel inefficient. Watch for the moment when decisiveness turns into deciding for both people."},{"title":"A way back to each other","body":"Ask how your delivery affected the conversation. Let the other person finish. Replace a unilateral solution with an agreement both of you can decline or revise."},{"title":"A practice for this week","body":"In one shared decision, ask what matters to the other person before presenting your preferred outcome."}],"prompt":"Can I remain powerful without needing to be in control of this interaction?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Creates direction and consequential outcomes.","elements":["Fire","Earth"],"prototype":{"value_influence":0.72,"competence_identity":0.78,"decisiveness":0.72,"stress_control":0.55,"autonomy_need":0.42,"conflict_directness":0.38},"signature":{"behavior.agency":0.88,"big5.conscientiousness":0.58,"motives.influence":0.84,"jung.perceiving":-0.42},"relational":{"gift":"agency and protection","need":"mutual respect and a strong counterpart","shadow":"agency can become control"}}$model$::jsonb),
('Alchemist', 'wonder-mirror-library-2026.09', $report${"name":"Alchemist","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Transforms intensity into meaning and change.","elements":["Fire","Water","Ether"],"opening":"You may experience life as material for transformation. Feeling, imagination, and meaning can make an ordinary encounter unusually vivid. The task is to give that depth a form that can survive ordinary life.","gift":"transformation and emotional range","need":"a bond that can hold change","shadow":"intensity can be mistaken for compatibility","chapters":[{"title":"How your mind moves","body":"You connect events to what they are becoming. You may see creative possibilities in disruption and hold contradictory feelings without wanting to flatten them."},{"title":"The way you come close","body":"You bring emotional range and a willingness to meet another person in change. Intensity can open a door; consistency determines whether it becomes a home."},{"title":"Conditions for connection","body":"You may need honest feeling, imaginative room, and dependable agreements. A relationship can be alive without continually reinventing its foundations."},{"title":"When pressure arrives","body":"A charged moment may feel like the whole truth of the relationship. Give temporary states enough time to become information before turning them into conclusions."},{"title":"A way back to each other","body":"Name the feeling, the specific event, and the request separately. Return to the conversation after the emotional peak and check which parts still feel true."},{"title":"A practice for this week","body":"Track one promise over a week. Notice how steadiness changes your experience of desire, trust, or creative freedom."}],"prompt":"What remains meaningful when this moment is no longer intense?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Transforms intensity into meaning and change.","elements":["Fire","Water","Ether"],"prototype":{"emotional_intensity":0.7,"value_meaning":0.82,"vulnerability_openness":0.5,"cognitive_contextual":0.48,"novelty_orientation":0.38,"value_beauty":0.42},"signature":{"big5.openness":0.76,"big5.emotional_sensitivity":0.72,"motives.meaning":0.82,"motives.beauty":0.58},"relational":{"gift":"transformation and emotional range","need":"a bond that can hold change","shadow":"intensity can be mistaken for compatibility"}}$model$::jsonb),
('Devotee', 'wonder-mirror-library-2026.09', $report${"name":"Devotee","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Organizes life around the depth of the bond.","elements":["Water","Earth"],"opening":"You may love through sustained attention. Small continuities matter: the remembered detail, the thoughtful return, the choice to stay present. Your care is most generous when it includes your own needs.","gift":"sustained emotional investment","need":"clear reciprocity","shadow":"devotion can become fusion or vigilance","chapters":[{"title":"How your mind moves","body":"You notice the condition of the bond. Changes in responsiveness or reciprocity may register quickly, sometimes before you have enough context to explain them."},{"title":"The way you come close","body":"You bring tenderness, loyalty, and investment. The depth of what you give can be a gift, but it does not oblige you to carry the entire relationship."},{"title":"Conditions for connection","body":"You may need clear affection, reliable contact, and mutual initiative. Ask what reciprocity looks like in practice rather than expecting the other person to infer your standard."},{"title":"When pressure arrives","body":"Uncertainty may invite extra effort, checking, or accommodation. More giving does not necessarily produce more security."},{"title":"A way back to each other","body":"State the unmet need without submitting a ledger of every contribution. Ask for a concrete change and watch whether it is sustained."},{"title":"A practice for this week","body":"Make one direct request before offering additional care. Let receiving be part of how you participate."}],"prompt":"Would I still choose this level of giving if I knew it would not earn reassurance?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Organizes life around the depth of the bond.","elements":["Water","Earth"],"prototype":{"closeness_need":0.82,"value_loyalty":0.78,"value_family":0.58,"reciprocity_sensitivity":0.68,"repair_orientation":0.58,"vulnerability_openness":0.42},"signature":{"motives.intimacy":0.9,"motives.belonging":0.7,"big5.agreeableness":0.62,"motives.autonomy":-0.28},"relational":{"gift":"sustained emotional investment","need":"clear reciprocity","shadow":"devotion can become fusion or vigilance"}}$model$::jsonb),
('Guardian', 'wonder-mirror-library-2026.09', $report${"name":"Guardian","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Creates safety and continuity around what matters.","elements":["Earth","Water"],"opening":"You may make belonging tangible through continuity. People can come to rely on the calm, practical conditions you create. Your steadiness can support growth when safety includes the freedom to change.","gift":"steadiness and practical care","need":"security with room to evolve","shadow":"protection can become rigidity","chapters":[{"title":"How your mind moves","body":"You value what has proved dependable. You often notice whether a plan can work in daily life, including the small details enthusiasm can overlook."},{"title":"The way you come close","body":"Love may look like showing up repeatedly. Familiar rituals and a trustworthy rhythm can matter more than spectacle."},{"title":"Conditions for connection","body":"You may need consistency, integrity, and shared expectations. A compatible relationship should also allow preferences and plans to be renegotiated."},{"title":"When pressure arrives","body":"Change may feel like a threat to something hard won. Notice whether you are protecting a real value or simply a familiar arrangement."},{"title":"A way back to each other","body":"Name what you are afraid of losing, then explore how that value might survive a different approach. Agree on a small, reversible experiment."},{"title":"A practice for this week","body":"Invite one modest change to a shared routine. Keep the underlying commitment explicit while allowing the form to move."}],"prompt":"What is worth preserving here, and what is merely familiar?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Creates safety and continuity around what matters.","elements":["Earth","Water"],"prototype":{"value_stability":0.82,"structure_preference":0.68,"value_loyalty":0.68,"value_family":0.62,"repair_orientation":0.5,"trust_baseline":0.38},"signature":{"motives.security":0.9,"behavior.pace_stability":0.82,"big5.conscientiousness":0.62,"motives.discovery":-0.25},"relational":{"gift":"steadiness and practical care","need":"security with room to evolve","shadow":"protection can become rigidity"}}$model$::jsonb),
('Maverick', 'wonder-mirror-library-2026.09', $report${"name":"Maverick","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Protects authorship of the self.","elements":["Fire","Air"],"opening":"You may place a high value on authorship: a life that feels chosen from the inside. Your originality can make space for others to be less conventional too. Closeness becomes possible when dependence can be voluntary without feeling like capture.","gift":"independence and originality","need":"intimacy without possession","shadow":"autonomy can become defensive distance","chapters":[{"title":"How your mind moves","body":"You question inherited assumptions and notice the costs of conformity. Sometimes the unconventional option is right; sometimes a familiar answer can still be freely chosen."},{"title":"The way you come close","body":"You bring independence, candor, and respect for difference. Let a partner know how to reach you without making them guess whether space means disinterest."},{"title":"Conditions for connection","body":"You may need autonomy, honest agreements, and acceptance without possession. Independence works best when both people can ask for connection."},{"title":"When pressure arrives","body":"A request may register as an attempt to control you before its actual scope is clear. Separate the request from the story it evokes."},{"title":"A way back to each other","body":"Say what you can offer and what you cannot. If you need distance, give it an agreed shape and return rather than leaving the relationship suspended."},{"title":"A practice for this week","body":"Accept one small act of care without immediately balancing the debt. Notice whether receiving actually reduces your freedom."}],"prompt":"What kind of closeness am I refusing because I have mistaken it for control?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Protects authorship of the self.","elements":["Fire","Air"],"prototype":{"autonomy_need":0.86,"value_freedom":0.82,"distinctiveness_need":0.74,"novelty_orientation":0.48,"conflict_directness":0.28},"signature":{"motives.autonomy":0.94,"behavior.agency":0.62,"big5.openness":0.54,"motives.belonging":-0.28},"relational":{"gift":"independence and originality","need":"intimacy without possession","shadow":"autonomy can become defensive distance"}}$model$::jsonb),
('Diplomat', 'wonder-mirror-library-2026.09', $report${"name":"Diplomat","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Preserves connection across difference.","elements":["Water","Air"],"opening":"You may have a gift for keeping contact possible across difference. You can hear several positions without making every disagreement a rupture. Your own position belongs in that conversation as well.","gift":"translation and repair","need":"mutuality rather than endless mediation","shadow":"peacekeeping can become self-erasure","chapters":[{"title":"How your mind moves","body":"Context and interpersonal consequences enter your reasoning early. This helps you translate between people, though it can make your own preference harder to hear."},{"title":"The way you come close","body":"You offer listening, repair, and an instinct for mutual understanding. Mediation should not become a permanent assignment in your closest relationships."},{"title":"Conditions for connection","body":"You may need considerate communication and someone willing to meet you halfway. Peace is more meaningful when it contains honest disagreement."},{"title":"When pressure arrives","body":"You may smooth the surface while privately accumulating frustration. Apparent agreement can leave both people working from the wrong information."},{"title":"A way back to each other","body":"Begin with the part you have not said. Use a clear preference rather than a softened suggestion, and allow the other person to respond."},{"title":"A practice for this week","body":"Express a low-stakes disagreement without immediately resolving the tension for everyone."}],"prompt":"What would I say here if maintaining harmony were not my responsibility?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Preserves connection across difference.","elements":["Water","Air"],"prototype":{"repair_orientation":0.8,"cognitive_contextual":0.62,"stress_accommodation":0.58,"trust_baseline":0.45,"belonging_need":0.5,"conflict_directness":-0.12},"signature":{"big5.agreeableness":0.84,"jung.feeling":0.52,"motives.belonging":0.62,"behavior.agency":-0.15},"relational":{"gift":"translation and repair","need":"mutuality rather than endless mediation","shadow":"peacekeeping can become self-erasure"}}$model$::jsonb),
('Catalyst', 'wonder-mirror-library-2026.09', $report${"name":"Catalyst","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Creates movement in people and situations.","elements":["Fire","Air"],"opening":"You may create movement wherever you become engaged. Your energy turns possibility into an invitation, a decision, or a first step. What begins with momentum becomes meaningful through attention to what follows.","gift":"momentum and activation","need":"a bond that can keep up without becoming chaotic","shadow":"motion can outrun reflection","chapters":[{"title":"How your mind moves","body":"You see openings and often act before every detail is settled. That can release a stalled situation, especially when you remain receptive to feedback after the first move."},{"title":"The way you come close","body":"You bring initiative and a sense that life can happen now. Make room for a partner whose enthusiasm arrives at a different pace."},{"title":"Conditions for connection","body":"You may need responsiveness, shared participation, and room for change. A sustainable bond also needs pauses that are not interpreted as withdrawal."},{"title":"When pressure arrives","body":"You may accelerate when slowing down would reveal useful information. A new plan can distract from a conversation that needs completion."},{"title":"A way back to each other","body":"Ask what was left behind by the speed of the interaction. Slow your reply, agree on a next step, and follow through before opening another front."},{"title":"A practice for this week","body":"Finish one relational promise before making the next invitation. Notice the difference between excitement and trust."}],"prompt":"What would become visible if I allowed this moment to stay still?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Creates movement in people and situations.","elements":["Fire","Air"],"prototype":{"social_initiation":0.68,"novelty_orientation":0.7,"decisiveness":0.55,"value_influence":0.48,"emotional_intensity":0.35,"conflict_directness":0.32},"signature":{"behavior.agency":0.66,"behavior.social_reach":0.75,"motives.discovery":0.7,"behavior.pace_stability":-0.5},"relational":{"gift":"momentum and activation","need":"a bond that can keep up without becoming chaotic","shadow":"motion can outrun reflection"}}$model$::jsonb),
('Scholar', 'wonder-mirror-library-2026.09', $report${"name":"Scholar","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Builds intimacy with truth through disciplined understanding.","elements":["Air","Earth"],"opening":"You may meet the world through disciplined inquiry. Understanding has its own pleasure, and careful thought can be a form of care. Intimacy asks that your ideas remain connected to the person having the experience.","gift":"clarity and intellectual depth","need":"space to think and a partner who values inquiry","shadow":"analysis can become distance","chapters":[{"title":"How your mind moves","body":"You prefer distinctions that can withstand scrutiny. Time to think may improve your answer. Let others know when reflection is active rather than leaving silence unexplained."},{"title":"The way you come close","body":"Shared inquiry and a well-formed conversation may draw you close. Emotional disclosure does not need to be theoretically complete before it can be offered."},{"title":"Conditions for connection","body":"You may need intellectual respect, solitude, and a partner who values questions. You also need permission to be uncertain about yourself."},{"title":"When pressure arrives","body":"You may move into explanation when a feeling is difficult to inhabit. The account can be accurate while the encounter still feels distant."},{"title":"A way back to each other","body":"Acknowledge the emotional impact before discussing the reasoning. Offer a simple feeling or need that has not yet been fully analyzed."},{"title":"A practice for this week","body":"In one conversation, replace an explanation with a sentence beginning “I felt…” and stop there long enough to be met."}],"prompt":"What do I know how to explain that I have not yet let myself feel?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Builds intimacy with truth through disciplined understanding.","elements":["Air","Earth"],"prototype":{"value_knowledge":0.88,"cognitive_systemizing":0.68,"ambiguity_tolerance":0.42,"structure_preference":0.4,"autonomy_need":0.32,"social_initiation":-0.25},"signature":{"big5.openness":0.62,"behavior.precision":0.58,"jung.extraversion":-0.55,"motives.discovery":0.62},"relational":{"gift":"clarity and intellectual depth","need":"space to think and a partner who values inquiry","shadow":"analysis can become distance"}}$model$::jsonb),
('Artisan', 'wonder-mirror-library-2026.09', $report${"name":"Artisan","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Makes inner experience tangible through form and beauty.","elements":["Ether","Earth","Water"],"opening":"You may make inner experience tangible through form, atmosphere, and detail. Beauty can be a way of paying attention. You deserve to be known beyond what you make or the world you curate around you.","gift":"sensibility and expression","need":"to be seen beyond output or aesthetics","shadow":"taste can become identity armor","chapters":[{"title":"How your mind moves","body":"You register texture, proportion, and subtle differences in expression. Your judgment may arrive as a felt coherence before you can explain its parts."},{"title":"The way you come close","body":"You offer attentive gestures and a sensitivity to shared environments. Let the person behind the gesture speak as plainly as the gesture itself."},{"title":"Conditions for connection","body":"You may need creative room, thoughtful attention, and interest in your inner process. Agreement in taste is less important than respect for what that taste means to you."},{"title":"When pressure arrives","body":"When exposed, you may retreat into refinement or become unusually exacting. A preference can become a defense against the messiness of being seen."},{"title":"A way back to each other","body":"Name the feeling underneath the aesthetic or practical complaint. Make the request understandable without requiring someone else to share your sensibility."},{"title":"A practice for this week","body":"Share something unfinished with a trusted person. Ask for company before asking for critique."}],"prompt":"What would I allow someone to see if it did not have to be beautifully expressed?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Makes inner experience tangible through form and beauty.","elements":["Ether","Earth","Water"],"prototype":{"value_beauty":0.88,"distinctiveness_need":0.68,"emotional_intensity":0.46,"cognitive_contextual":0.4,"value_meaning":0.42,"novelty_orientation":0.25},"signature":{"motives.beauty":0.9,"big5.openness":0.7,"jung.feeling":0.32,"behavior.precision":0.18},"relational":{"gift":"sensibility and expression","need":"to be seen beyond output or aesthetics","shadow":"taste can become identity armor"}}$model$::jsonb),
('Steward', 'wonder-mirror-library-2026.09', $report${"name":"Steward","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Takes responsibility for people, systems, and continuity.","elements":["Earth","Ether"],"opening":"You may show care by accepting responsibility for what others depend on. You notice the work that keeps life functioning. A shared life should make you a participant in care, not its permanent infrastructure.","gift":"responsibility and care","need":"shared burden rather than permanent caretaking","shadow":"service can become over-functioning","chapters":[{"title":"How your mind moves","body":"You consider consequences, duties, and the people who will be affected. Your judgment can hold a longer horizon than immediate convenience."},{"title":"The way you come close","body":"You bring practical support and a capacity to stay with important commitments. Being needed is not the only evidence that you are loved."},{"title":"Conditions for connection","body":"You may need shared responsibility, appreciation, and the freedom to rest without explanation. Look for initiative that appears before you have to delegate it."},{"title":"When pressure arrives","body":"You may take on more precisely when your own capacity is smallest. Quiet over-functioning can conceal how uneven the arrangement has become."},{"title":"A way back to each other","body":"Make the invisible work visible without treating exhaustion as a moral credential. Agree on ownership of tasks, not merely occasional help."},{"title":"A practice for this week","body":"Leave one appropriate responsibility with someone else. Resist supervising the entire result."}],"prompt":"What do I need when I am not being useful to anyone?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Takes responsibility for people, systems, and continuity.","elements":["Earth","Ether"],"prototype":{"value_service":0.78,"value_family":0.58,"value_stability":0.62,"repair_orientation":0.55,"competence_identity":0.48,"stress_accommodation":0.42},"signature":{"big5.conscientiousness":0.58,"big5.agreeableness":0.65,"motives.security":0.62,"motives.meaning":0.62},"relational":{"gift":"responsibility and care","need":"shared burden rather than permanent caretaking","shadow":"service can become over-functioning"}}$model$::jsonb),
('Visionary', 'wonder-mirror-library-2026.09', $report${"name":"Visionary","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Orients toward futures that do not yet exist.","elements":["Air","Ether","Fire"],"opening":"You may feel the pull of a future before it has a recognizable shape. Possibility, meaning, and imagination organize your attention. Love needs a place in that future and a lived presence today.","gift":"possibility and long-range imagination","need":"someone who can engage the future without dismissing the present","shadow":"possibility can outrun execution","chapters":[{"title":"How your mind moves","body":"You connect distant ideas and imagine systems beyond current constraints. Translation matters: other people may need the next concrete step before they can follow the horizon."},{"title":"The way you come close","body":"You invite a partner into a larger sense of becoming. Their present experience needs as much curiosity as the life you imagine together."},{"title":"Conditions for connection","body":"You may need imaginative engagement and a willingness to grow. You also benefit from someone who can ask practical questions without being cast as the enemy of possibility."},{"title":"When pressure arrives","body":"The next chapter may become more compelling than the demands of the current one. Ordinary maintenance can then feel unfairly small."},{"title":"A way back to each other","body":"Ask which present need has been postponed in the name of the future. Make one promise you can fulfill now."},{"title":"A practice for this week","body":"Translate a large shared hope into one action this week, chosen together."}],"prompt":"How does the future I describe feel to the person living with me in the present?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Orients toward futures that do not yet exist.","elements":["Air","Ether","Fire"],"prototype":{"value_meaning":0.7,"value_influence":0.52,"novelty_orientation":0.58,"cognitive_contextual":0.62,"ambiguity_tolerance":0.62,"distinctiveness_need":0.45},"signature":{"jung.intuition":0.9,"big5.openness":0.86,"motives.meaning":0.7,"behavior.pace_stability":-0.38},"relational":{"gift":"possibility and long-range imagination","need":"someone who can engage the future without dismissing the present","shadow":"possibility can outrun execution"}}$model$::jsonb),
('Sentinel', 'wonder-mirror-library-2026.09', $report${"name":"Sentinel","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Notices risk early and protects what has been entrusted.","elements":["Earth","Air"],"opening":"You may notice what is vulnerable before others see a problem. Discernment helps you protect what has been entrusted to you. Trust grows when attention to risk can also register evidence of reliability.","gift":"discernment and prevention","need":"evidence of reliability","shadow":"discernment can become chronic vigilance","chapters":[{"title":"How your mind moves","body":"You examine consistency, omissions, and the gap between claims and actions. Your caution is most useful when it can update as new evidence arrives."},{"title":"The way you come close","body":"You bring careful judgment and respect for commitments. A partner also needs to know when they have earned trust, rather than facing a test with no finish line."},{"title":"Conditions for connection","body":"You may need dependable behavior, clear boundaries, and answers that survive follow-up. Reassurance is stronger when it is concrete and reciprocal."},{"title":"When pressure arrives","body":"An ambiguous event may sharpen vigilance. Monitoring can create a temporary feeling of control without resolving the uncertainty beneath it."},{"title":"A way back to each other","body":"Describe the specific breach or concern. Agree on what repair would look like, including how you will recognize when enough has been done."},{"title":"A practice for this week","body":"Record one piece of evidence that supports trust alongside one concern. Give both the same standard of scrutiny."}],"prompt":"What evidence would actually allow me to relax my conclusion?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Notices risk early and protects what has been entrusted.","elements":["Earth","Air"],"prototype":{"value_stability":0.72,"structure_preference":0.72,"reciprocity_sensitivity":0.48,"trust_baseline":-0.12,"cognitive_systemizing":0.5,"stress_control":0.4},"signature":{"behavior.precision":0.72,"motives.security":0.75,"big5.conscientiousness":0.65,"big5.emotional_sensitivity":0.25},"relational":{"gift":"discernment and prevention","need":"evidence of reliability","shadow":"discernment can become chronic vigilance"}}$model$::jsonb),
('Muse', 'wonder-mirror-library-2026.09', $report${"name":"Muse","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Creates aliveness through presence, feeling, and imaginative attention.","elements":["Water","Fire","Ether"],"opening":"You may bring aliveness through attention, imagination, and emotional presence. An encounter can change in your company. Being evocative is different from being understood, and you deserve the latter.","gift":"inspiration and emotional texture","need":"to be known beyond projection","shadow":"being desired can substitute for being understood","chapters":[{"title":"How your mind moves","body":"Feeling and association may lead you toward insights a linear account would miss. Make room to test whether an evocative possibility fits the situation."},{"title":"The way you come close","body":"You offer warmth, texture, and imaginative attention. A partner should remain interested when you are ordinary, tired, or less available to inspire."},{"title":"Conditions for connection","body":"You may need affection, creative freedom, and curiosity about your less polished interior. Admiration alone cannot carry mutual intimacy."},{"title":"When pressure arrives","body":"Changes in attention may feel like changes in your value. You may feel pulled toward becoming more compelling rather than asking what has happened."},{"title":"A way back to each other","body":"State the need underneath the performance. Ask to be met in the feeling rather than attempting to restore the atmosphere on your own."},{"title":"A practice for this week","body":"Let a trusted person see an unremarkable moment without embellishing it. Notice whether the connection remains."}],"prompt":"Where am I being appreciated as an image rather than encountered as a person?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Creates aliveness through presence, feeling, and imaginative attention.","elements":["Water","Fire","Ether"],"prototype":{"value_beauty":0.66,"emotional_intensity":0.62,"novelty_orientation":0.42,"closeness_need":0.4,"recognition_need":0.35,"cognitive_contextual":0.42},"signature":{"motives.beauty":0.72,"big5.openness":0.7,"behavior.social_reach":0.4,"motives.intimacy":0.42},"relational":{"gift":"inspiration and emotional texture","need":"to be known beyond projection","shadow":"being desired can substitute for being understood"}}$model$::jsonb),
('Strategist', 'wonder-mirror-library-2026.09', $report${"name":"Strategist","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Reads systems of people and incentives before acting.","elements":["Air","Fire","Earth"],"opening":"You may understand a situation by reading its moving parts: motives, incentives, timing, and consequence. Foresight can be protective. Intimacy also needs moments in which nothing is being optimized.","gift":"foresight and calibrated action","need":"trust that does not require surrendering discernment","shadow":"strategy can become guardedness or instrumental thinking","chapters":[{"title":"How your mind moves","body":"You hold several possible outcomes in mind before acting. This can support measured decisions, provided other people remain people rather than variables in a model."},{"title":"The way you come close","body":"You bring discernment and calibrated commitment. A partner may need access to your uncertainty as well as the conclusion you have carefully prepared."},{"title":"Conditions for connection","body":"You may need candor, competence, and a relationship in which trust is compatible with independent judgment. Reciprocity matters more than maintaining an advantage."},{"title":"When pressure arrives","body":"You may manage the interaction to reduce vulnerability. A carefully positioned response can leave your actual need unavailable to the other person."},{"title":"A way back to each other","body":"Say what you hoped would happen and what you feared. Avoid testing someone with a question whose real purpose you have concealed."},{"title":"A practice for this week","body":"Make one direct request without managing the other person toward the answer first."}],"prompt":"What would I say if I did not need to protect my position?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Reads systems of people and incentives before acting.","elements":["Air","Fire","Earth"],"prototype":{"cognitive_systemizing":0.68,"cognitive_contextual":0.55,"decisiveness":0.58,"value_influence":0.48,"autonomy_need":0.4,"emotional_intensity":-0.18},"signature":{"behavior.objectivity":0.72,"behavior.agency":0.6,"jung.feeling":-0.5,"big5.conscientiousness":0.42},"relational":{"gift":"foresight and calibrated action","need":"trust that does not require surrendering discernment","shadow":"strategy can become guardedness or instrumental thinking"}}$model$::jsonb),
('Connector', 'wonder-mirror-library-2026.09', $report${"name":"Connector","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Builds energy through people, belonging, and exchange.","elements":["Water","Air","Fire"],"opening":"You may make people feel that there is room for them. Social energy, inclusion, and exchange can be genuine sources of meaning. Depth asks for attention that does not need an audience.","gift":"social vitality and inclusion","need":"depth beneath breadth","shadow":"connection can become dependence on social reflection","chapters":[{"title":"How your mind moves","body":"You often think through conversation and notice how people connect. Your social awareness is useful, though a group response need not settle your private judgment."},{"title":"The way you come close","body":"You bring invitations, warmth, and relational momentum. Make room for the quieter intimacy that grows when two people are no longer performing their most engaging selves."},{"title":"Conditions for connection","body":"You may need responsive contact and a shared social life. A partner with a smaller social appetite can still be deeply invested."},{"title":"When pressure arrives","body":"A lull in contact may invite more reaching out or a search for reassurance elsewhere. Pause long enough to identify whose attention you actually want."},{"title":"A way back to each other","body":"Speak to the person involved before seeking a consensus among friends. Ask for what would make the connection feel more present."},{"title":"A practice for this week","body":"Choose one unhurried conversation without multitasking or adding more people to the plan."}],"prompt":"With whom do I feel known when I am not being socially useful or entertaining?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Builds energy through people, belonging, and exchange.","elements":["Water","Air","Fire"],"prototype":{"social_initiation":0.82,"belonging_need":0.68,"closeness_need":0.42,"recognition_need":0.38,"trust_baseline":0.3,"repair_orientation":0.3},"signature":{"behavior.social_reach":0.9,"big5.extraversion":0.86,"motives.belonging":0.68,"jung.extraversion":0.88},"relational":{"gift":"social vitality and inclusion","need":"depth beneath breadth","shadow":"connection can become dependence on social reflection"}}$model$::jsonb),
('Idealist', 'wonder-mirror-library-2026.09', $report${"name":"Idealist","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Organizes choices around what ought to be true.","elements":["Ether","Water","Air"],"opening":"You may organize life around what deserves to be true. Conviction can make your care principled and your commitments serious. A relationship must still have room for imperfect people who are learning.","gift":"conviction and moral imagination","need":"shared seriousness without total ideological sameness","shadow":"ideals can become disappointment with ordinary humanity","chapters":[{"title":"How your mind moves","body":"You notice the distance between stated values and lived choices. This can clarify what matters, as long as disagreement is not automatically treated as moral failure."},{"title":"The way you come close","body":"You bring seriousness, loyalty, and a desire for shared meaning. Ordinary kindness may reveal values more reliably than perfect philosophical agreement."},{"title":"Conditions for connection","body":"You may need integrity and a partner willing to examine how they live. Shared direction can coexist with different language, experience, or conclusions."},{"title":"When pressure arrives","body":"Disappointment may become a global judgment about someone’s character. Distinguish a harmful pattern from a repairable human mistake."},{"title":"A way back to each other","body":"Name the value that was hurt and the behavior that would restore confidence. Leave room for an account of the event you have not considered."},{"title":"A practice for this week","body":"Notice one imperfect action that still expresses real care. Let complexity inform your standards without abandoning them."}],"prompt":"Am I asking for integrity, or for freedom from the disappointment of another person’s humanity?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Organizes choices around what ought to be true.","elements":["Ether","Water","Air"],"prototype":{"value_meaning":0.8,"value_service":0.65,"value_loyalty":0.42,"cognitive_contextual":0.48,"belonging_need":0.38,"ambiguity_tolerance":0.3},"signature":{"motives.meaning":0.86,"jung.feeling":0.58,"big5.openness":0.55,"big5.agreeableness":0.5},"relational":{"gift":"conviction and moral imagination","need":"shared seriousness without total ideological sameness","shadow":"ideals can become disappointment with ordinary humanity"}}$model$::jsonb),
('Pilgrim', 'wonder-mirror-library-2026.09', $report${"name":"Pilgrim","version":"wonder-mirror-library-2026.09","model_version":"wonder-archetypes-v2.0","essence":"Uses experience as a path toward self-knowledge.","elements":["Ether","Air","Fire"],"opening":"You may treat experience as a path toward deeper understanding. Growth matters because you want your life to become more consciously chosen. Belonging can be part of that journey rather than the place where it ends.","gift":"growth orientation and reflective curiosity","need":"a relationship that permits becoming","shadow":"searching can become postponement of commitment","chapters":[{"title":"How your mind moves","body":"You ask what an experience reveals and how it changes your direction. Reflection becomes useful when it also informs the next ordinary choice."},{"title":"The way you come close","body":"You bring openness to becoming and a willingness to question familiar patterns. A partner needs to know what you are choosing while you are still evolving."},{"title":"Conditions for connection","body":"You may need space for discovery, honest conversation, and a relationship that can change shape through mutual agreement."},{"title":"When pressure arrives","body":"A sense that something more authentic lies elsewhere may postpone engagement with the difficulty here. Growth and departure are not always the same decision."},{"title":"A way back to each other","body":"Describe what is changing in you without presenting it as a completed verdict on the relationship. Ask what can evolve together."},{"title":"A practice for this week","body":"Choose one present commitment that expresses the person you are becoming. Let practice carry some of the work reflection has been doing."}],"prompt":"What am I ready to live now, before I fully understand where it leads?","note":"An interpretive framework, not a diagnosis or fixed identity. Keep what fits; question what does not."}$report$::jsonb, $model${"essence":"Uses experience as a path toward self-knowledge.","elements":["Ether","Air","Fire"],"prototype":{"value_meaning":0.72,"novelty_orientation":0.52,"autonomy_need":0.42,"cognitive_contextual":0.5,"distinctiveness_need":0.4,"vulnerability_openness":0.25},"signature":{"motives.meaning":0.72,"motives.discovery":0.62,"big5.openness":0.7,"motives.autonomy":0.45},"relational":{"gift":"growth orientation and reflective curiosity","need":"a relationship that permits becoming","shadow":"searching can become postponement of commitment"}}$model$::jsonb)
