-- Versioned archetype registry. Only the server can access scoring definitions.
create table if not exists public.archetype_catalog (name text primary key, report_version text not null, report jsonb not null, definition jsonb not null, updated_at timestamptz not null default now());
alter table public.archetype_catalog enable row level security;
revoke all on public.archetype_catalog from anon,authenticated;
grant select,insert,update,delete on public.archetype_catalog to service_role;
on conflict(name) do update set report_version=excluded.report_version, report=excluded.report, definition=excluded.definition,updated_at=now();
alter table public.person_model_snapshots add column if not exists primary_archetype text references public.archetype_catalog(name);
alter table public.person_model_snapshots add column if not exists secondary_archetype text references public.archetype_catalog(name);
alter table public.mirror_reports add column if not exists snapshot_id uuid references public.person_model_snapshots(id) on delete cascade;
create unique index if not exists mirror_reports_snapshot_unique on public.mirror_reports(snapshot_id);
create index if not exists journal_entries_user_created on public.journal_entries(user_id,created_at desc);
create index if not exists ai_messages_user_conversation_created on public.ai_messages(user_id,conversation_id,created_at desc);
